// Rodrigues' rotation formula : rotates v around u
vec3 rot(vec3 v, vec3 u, float a){
    float c = cos(a);
    float s = sin(a);
    return v * c + cross(u, v) * s + u * dot(u, v) * (1. - c);
}

// random and noise functions

float hash(float p) {
    p = fract(p * 0.011); p *= p + 7.5; p *= p + p;
    return fract(p);
}

float noise(vec3 x) {
    const vec3 st = vec3(110, 241, 171);

    vec3 i = floor(x);
    vec3 f = fract(x);

    float n = dot(i, st);

    vec3 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(mix( hash(n + dot(st, vec3(0, 0, 0))), hash(n + dot(st, vec3(1, 0, 0))), u.x),
                   mix( hash(n + dot(st, vec3(0, 1, 0))), hash(n + dot(st, vec3(1, 1, 0))), u.x), u.y),
               mix(mix( hash(n + dot(st, vec3(0, 0, 1))), hash(n + dot(st, vec3(1, 0, 1))), u.x),
                   mix( hash(n + dot(st, vec3(0, 1, 1))), hash(n + dot(st, vec3(1, 1, 1))), u.x), u.y), u.z);
}

// fractal brownian motion : noise with octaves
float fbm(vec3 x) {
	float v = 0.0;
	float a = 0.5;
	vec3 shift = vec3(100);
	for (int i = 0; i < 4; ++i) { // 4 octaves
		v += a * noise(x);
		x = x * 2.5 + shift;
		a *= 0.5;
	}
	return v;
}
float hash11(float p)
{
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash12(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

mat2 rotate2d(float theta)
{
    float c = cos(theta);
    float s = sin(theta);
    return mat2(
        c, -s,
        s, c
    );
}

float noise(vec2 p)
{
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float a = hash12(ip);
    float b = hash12(ip + vec2(1, 0));
    float c = hash12(ip + vec2(0, 1));
    float d = hash12(ip + vec2(1, 1));

    vec2 t = smoothstep(0.0, 1.0, fp);
    return mix(mix(a, b, t.x), mix(c, d, t.x), t.y);
}

float fbm(vec2 p, int octaveCount)
{
    float value = 0.0;
    float amplitude = 0.5;
    for (int i = 0; i < octaveCount; ++i)
    {
        value += amplitude * noise(p);
        p *= rotate2d(0.45);
        p *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}
// generate the background map
vec3 background(in vec3 rd){

    vec3 gc = vec3(0., 0., 1.); // galaxy center

    float i = (1.- abs(rd.y - gc.y));

    vec3 val = vec3(pow(i, 8.)) * fbm((rd+vec3(2., 1, -4.))*10.)*0.5;
    val *= clamp(dot(rd.xz, gc.xz), 0.,1.);

    val *= 0.5/distance(vec3(rd.x/2.5, rd.y*6., rd.z), gc);

    val.r *= 1./distance(rd, gc);
    val.b *= distance(rd, gc);

    val.g = (val.r + val.b) / 4.;

    val /= fbm(-rd);

    // add dust
    val = clamp(val, 0., 1.);
    if(abs(gc.y - rd.y) <= 0.1)
        val -= fbm(rd*30.)*vec3(1.-abs(gc.y - rd.y)*10.) * vec3(0.2, 0.8, 0.9) * pow(clamp(dot(rd, gc), 0., 1.), 1.5);

    // stars
    float s = fbm(rd * 100.);
    s = pow(s*1.18, 15.0);
    val += s;



    return val;
}




const float G = 0.01;
const float c = 100.;


void mainVR( out vec4 fragColor, in vec2 fragCoord, in vec3 ro, in vec3 rd )
{
	//get coords and direction
	vec3 dir=rd;
	vec3 from=ro;

	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=mat2(cos(iTime*0.02),sin(iTime*0.02),-sin(iTime*0.02),cos(iTime*0.02) );// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.03,1.);	
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
    vec4 o =fragColor;
    vec2 F=fragCoord;
      vec2 R = iResolution.xy; 
    o-=o;
    for(float d,t = -iTime*.01, i = 0. ; i > -1.; i -= .06 )          	
    {   d = fract( i -3.*t );                                          	
        vec4 c = vec4( ( F - R *.5 ) / R.y *d ,i,0 ) * 28.;            	
        for (int j=0 ; j++ <27; )                                      	
            c.xzyw = abs( c / dot(c,c)                                 	
                    -vec4( 7.-.2*sin(t) , 6.3 , .7 , 1.-cos(t/.8))/7.);	
       o -= c * c.yzww  * d--*d  / vec4(2,1,1,1);                     
    }
      uv /= 1.0 - uv.y * 3.5;

	vec3 dir=vec3(uv*zoom,1.);
;
  vec2 uv3 = fragCoord/iResolution.xy;
    uv3 = 2.0 * uv3 - 1.0;
    uv3.x *= iResolution.x / iResolution.y;
 uv3 /= 1.0 - uv3.y * 3.5;
    uv3 += 2.0 * fbm(uv3+0.8*iTime, 10) - 1.0;

    float dist = abs(uv3.x);
    vec3 col3 = vec3(0.2, 1.3, 0.8) * pow(mix(0.0, 0.07, hash11(iTime)) / dist, 1.0);

    col3 = pow(col3, vec3(1.0));
 vec3 ro = vec3(5., 0., -10); // origin of the ray
    vec3 rd = normalize(vec3(uv, 1.)); // inital direction of the ray

    float time2 = iTime;

    vec3 col = vec3(0.); // pixel color

    vec4 bh = vec4(3., 0., 0., 100000.); // black hole (x, y, z, mass)
    // animate black hole
    float k = 4.;
    bh.x += cos(time2)*k;
    bh.y += sin(time2)*k;


    // rotate towards the black hole
    vec3 cam = vec3(0., 0., 1.);



    vec3 rb = bh.xyz - ro;

    float a = acos(dot(rb, cam) / length(rb));
    vec3 rn = normalize(cross(rb, cam));

    rd = rot(rd, rn, -a*0.8+sin(time2)*0.1);



    // calculate the distance to the closest point between the ray and the black hole
    float t = dot(rd, bh.xyz - ro);

    vec3 v = ro + rd * t - bh.xyz; // vector between closest point and blackhole
    float r = length(v); // its distance


    // Schwarzfield radius
    float rs = 2. * G * bh.w / (c*c);
    if(r >= rs){
        vec3 nml = normalize(cross(v, rd)); // axis of rotation of the ray
        float a = 4. * bh.w * G / (r * c * c); // angle of deflection caused by gravitational field

        rd = rot(rd, nml, a);

        col = background(rd);//texture(iChannel0, rd).rgb;
    }
	vec3 from=vec3(1.,.5,0.5)*col*o.xyz+col3;


	mainVR(fragColor, fragCoord, from, dir);	
    fragColor+=vec4(col+col3,1.);
}
